-- Phase E: durable memory, project-scoped isolation, retrieval, provenance and governance.
ALTER TABLE public.projects ADD COLUMN IF NOT EXISTS memory_enabled BOOLEAN NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS public.aether_memories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, project_id UUID REFERENCES public.projects(id) ON DELETE CASCADE, scope TEXT NOT NULL CHECK (scope IN ('global','project')), memory_type TEXT NOT NULL DEFAULT 'fact' CHECK (memory_type IN ('fact','preference','context','instruction','goal')), content TEXT NOT NULL CHECK (char_length(trim(content)) BETWEEN 1 AND 12000), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','superseded','deleted')), persistence_mode TEXT NOT NULL DEFAULT 'explicit' CHECK (persistence_mode IN ('explicit','approved_candidate')), reason TEXT NOT NULL DEFAULT '', confidence NUMERIC(5,4) CHECK (confidence IS NULL OR confidence >= 0 AND confidence <= 1), importance NUMERIC(5,4) NOT NULL DEFAULT 0.5 CHECK (importance >= 0 AND importance <= 1), version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0), previous_memory_id UUID REFERENCES public.aether_memories(id) ON DELETE SET NULL, source_conversation_id UUID REFERENCES public.aax_conversations(id) ON DELETE SET NULL, source_message_id UUID REFERENCES public.aax_conversation_messages(id) ON DELETE SET NULL, source_task_id UUID REFERENCES public.tasks(id) ON DELETE SET NULL, last_used_at TIMESTAMPTZ, deleted_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((scope = 'global' AND project_id IS NULL) OR (scope = 'project' AND project_id IS NOT NULL)));
CREATE INDEX IF NOT EXISTS aether_memories_owner_scope_idx ON public.aether_memories(owner_id, scope, status);
CREATE INDEX IF NOT EXISTS aether_memories_project_idx ON public.aether_memories(owner_id, project_id, status);
CREATE INDEX IF NOT EXISTS aether_memories_updated_idx ON public.aether_memories(owner_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS aether_memories_search_idx ON public.aether_memories USING gin (to_tsvector('simple', content));
CREATE TABLE IF NOT EXISTS public.aether_memory_candidates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, project_id UUID REFERENCES public.projects(id) ON DELETE CASCADE, scope TEXT NOT NULL CHECK (scope IN ('global','project')), memory_type TEXT NOT NULL DEFAULT 'fact' CHECK (memory_type IN ('fact','preference','context','instruction','goal')), content TEXT NOT NULL CHECK (char_length(trim(content)) BETWEEN 1 AND 12000), status TEXT NOT NULL DEFAULT 'candidate' CHECK (status IN ('candidate','approved','rejected','promoted','expired')), reason TEXT NOT NULL DEFAULT '', confidence NUMERIC(5,4) CHECK (confidence IS NULL OR confidence >= 0 AND confidence <= 1), source_conversation_id UUID REFERENCES public.aax_conversations(id) ON DELETE SET NULL, source_message_id UUID REFERENCES public.aax_conversation_messages(id) ON DELETE SET NULL, source_task_id UUID REFERENCES public.tasks(id) ON DELETE SET NULL, provenance JSONB NOT NULL DEFAULT '{}'::jsonb, reviewed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, reviewed_at TIMESTAMPTZ, memory_id UUID REFERENCES public.aether_memories(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((scope = 'global' AND project_id IS NULL) OR (scope = 'project' AND project_id IS NOT NULL)));
CREATE INDEX IF NOT EXISTS aether_memory_candidates_owner_idx ON public.aether_memory_candidates(owner_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS aether_memory_candidates_project_idx ON public.aether_memory_candidates(owner_id, project_id, status);
CREATE TABLE IF NOT EXISTS public.aether_memory_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, memory_id UUID REFERENCES public.aether_memories(id) ON DELETE SET NULL, candidate_id UUID REFERENCES public.aether_memory_candidates(id) ON DELETE SET NULL, event_type TEXT NOT NULL CHECK (event_type IN ('created','retrieved','updated','superseded','deleted','candidate_created','candidate_approved','candidate_rejected','candidate_expired','exported')), actor_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, source_conversation_id UUID REFERENCES public.aax_conversations(id) ON DELETE SET NULL, source_task_id UUID REFERENCES public.tasks(id) ON DELETE SET NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS aether_memory_events_owner_idx ON public.aether_memory_events(owner_id, created_at DESC);
CREATE INDEX IF NOT EXISTS aether_memory_events_memory_idx ON public.aether_memory_events(memory_id, created_at DESC);
ALTER TABLE public.aether_memories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.aether_memory_candidates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.aether_memory_events ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.aether_memories TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.aether_memory_candidates TO authenticated;
GRANT SELECT ON public.aether_memory_events TO authenticated;
GRANT ALL ON public.aether_memories, public.aether_memory_candidates, public.aether_memory_events TO service_role;
DROP POLICY IF EXISTS "own aether memories" ON public.aether_memories;
CREATE POLICY "own aether memories" ON public.aether_memories FOR ALL TO authenticated USING ((select auth.uid()) = owner_id) WITH CHECK ((select auth.uid()) = owner_id AND (project_id IS NULL OR EXISTS (SELECT 1 FROM public.projects p WHERE p.id = project_id AND p.owner_id = (select auth.uid()))));
DROP POLICY IF EXISTS "own aether memory candidates" ON public.aether_memory_candidates;
CREATE POLICY "own aether memory candidates" ON public.aether_memory_candidates FOR ALL TO authenticated USING ((select auth.uid()) = owner_id) WITH CHECK ((select auth.uid()) = owner_id AND (project_id IS NULL OR EXISTS (SELECT 1 FROM public.projects p WHERE p.id = project_id AND p.owner_id = (select auth.uid()))));
DROP POLICY IF EXISTS "own aether memory events" ON public.aether_memory_events;
CREATE POLICY "own aether memory events" ON public.aether_memory_events FOR SELECT TO authenticated USING ((select auth.uid()) = owner_id);
DROP TRIGGER IF EXISTS aether_memories_updated ON public.aether_memories;
CREATE TRIGGER aether_memories_updated BEFORE UPDATE ON public.aether_memories FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
DROP TRIGGER IF EXISTS aether_memory_candidates_updated ON public.aether_memory_candidates;
CREATE TRIGGER aether_memory_candidates_updated BEFORE UPDATE ON public.aether_memory_candidates FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE FUNCTION public.retrieve_aether_memories(p_query TEXT, p_project_id UUID DEFAULT NULL, p_limit INTEGER DEFAULT 8, p_min_rank REAL DEFAULT 0.02) RETURNS TABLE (id UUID, project_id UUID, scope TEXT, memory_type TEXT, content TEXT, reason TEXT, confidence NUMERIC, importance NUMERIC, version INTEGER, source_conversation_id UUID, source_message_id UUID, rank REAL) LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$ SELECT m.id, m.project_id, m.scope, m.memory_type, m.content, m.reason, m.confidence, m.importance, m.version, m.source_conversation_id, m.source_message_id, CASE WHEN nullif(trim(p_query), '') IS NULL THEN 0.0::real ELSE ts_rank_cd(to_tsvector('simple', m.content), plainto_tsquery('simple', p_query)) END AS rank FROM public.aether_memories m WHERE m.owner_id = (select auth.uid()) AND m.status = 'active' AND m.deleted_at IS NULL AND (m.scope = 'global' OR (m.scope = 'project' AND p_project_id IS NOT NULL AND m.project_id = p_project_id)) AND (nullif(trim(p_query), '') IS NULL OR ts_rank_cd(to_tsvector('simple', m.content), plainto_tsquery('simple', p_query)) >= p_min_rank) ORDER BY rank DESC, m.importance DESC, COALESCE(m.confidence, 0) DESC, m.updated_at DESC LIMIT LEAST(GREATEST(p_limit, 1), 50); $$;
REVOKE ALL ON FUNCTION public.retrieve_aether_memories(TEXT, UUID, INTEGER, REAL) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.retrieve_aether_memories(TEXT, UUID, INTEGER, REAL) TO authenticated, service_role;
COMMENT ON TABLE public.aether_memories IS 'Phase E durable long-term memory. Only active, authorized memories are eligible for retrieval.';
COMMENT ON TABLE public.aether_memory_candidates IS 'Phase E governed memory candidates. Candidates are never used as memory until approved/promoted.';
COMMENT ON TABLE public.aether_memory_events IS 'Phase E append-only memory provenance/audit trail.';
